import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Proxmox and Ceph Ditch the old SAN","description":"","frontmatter":{"title":"Proxmox and Ceph Ditch the old SAN","date":"2026-06-25T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["Ceph","分布式存储","存储集群","高可用性","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Proxmox_and_Ceph_Ditch_the_old_SAN.md","filePath":"posts/2026/Proxmox_and_Ceph_Ditch_the_old_SAN.md","lastUpdated":null}'),l={name:"posts/2026/Proxmox_and_Ceph_Ditch_the_old_SAN.md"};function i(h,t,d,n,s,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="proxmox-and-ceph-告别传统-san" tabindex="-1">Proxmox and Ceph：告别传统 SAN <a class="header-anchor" href="#proxmox-and-ceph-告别传统-san" aria-label="Permalink to &quot;Proxmox and Ceph：告别传统 SAN&quot;">​</a></h1><h2 id="演讲者背景" tabindex="-1">演讲者背景 <a class="header-anchor" href="#演讲者背景" aria-label="Permalink to &quot;演讲者背景&quot;">​</a></h2><p>Alex Gorbachev，Intelligent System Services 创始人，拥有 32 年 IT 从业经验，曾从事实验室物理研究。公司从早期的 Alphas、Sun、EMC、Oracle 等高端企业级存储起步，2013 年在 Santa Clara 的 Ceph Days 上结识 Sage Weil 和 Inktank 团队后开始接触 Ceph。2013 年搭建测试实验室，一度拥有全球最快的 Ceph 集群。2018 年在温哥华 Ceph Summit 期间加入 Ceph Foundation。目前拥有超过 200 家客户，主要服务于中端市场——银行、学校、医院、警局、教堂等对稳定性和可用性要求极高的机构。</p><p>Alex 特别感谢 Broadcom 的涨价策略，称其&quot;有力推动了向开源的大规模迁移&quot;，促使许多原本使用 VMware 的保守型客户开始考虑 Proxmox 和 Ceph。</p><h2 id="传统-san-存储的核心问题" tabindex="-1">传统 SAN 存储的核心问题 <a class="header-anchor" href="#传统-san-存储的核心问题" aria-label="Permalink to &quot;传统 SAN 存储的核心问题&quot;">​</a></h2><h3 id="_1-瓶颈与守门人" tabindex="-1">1. 瓶颈与守门人 <a class="header-anchor" href="#_1-瓶颈与守门人" aria-label="Permalink to &quot;1. 瓶颈与守门人&quot;">​</a></h3><p>传统存储阵列的本质问题在于<strong>控制器即守门人（gatekeeper）</strong>。客户端必须排队通过控制器才能访问数据，无论阵列多么强大，这一架构瓶颈始终存在。即使增加控制器数量（两个、四个），问题本质不变。</p><h3 id="_2-单点故障与厂商锁定" tabindex="-1">2. 单点故障与厂商锁定 <a class="header-anchor" href="#_2-单点故障与厂商锁定" aria-label="Permalink to &quot;2. 单点故障与厂商锁定&quot;">​</a></h3><ul><li>传统阵列后端是<strong>黑盒（proprietary IP）</strong>，用户无法了解数据如何分配、后端做出何种决策</li><li>升级硬盘时经常被告知&quot;必须购买全新阵列，旧型号不支持&quot;</li><li>无法向厂商提交 PR 来改进产品</li><li>前端接口设计脱离实际：将 NAS 和 Volume 等概念混为一谈，用户必须按照厂商设计的逻辑思考</li></ul><h3 id="_3-lun-分配不公" tabindex="-1">3. LUN 分配不公 <a class="header-anchor" href="#_3-lun-分配不公" aria-label="Permalink to &quot;3. LUN 分配不公&quot;">​</a></h3><p>SCSI 的 ALUA（Asymmetric Logical Unit Assignment）机制允许阵列向客户端告知最优路径，但厂商往往优先为自家前端产品提供更优的性能和可用性（如 EMC PowerPath），破坏了标准的公平性。</p><h2 id="三种存储方案在-proxmox-中的对比" tabindex="-1">三种存储方案在 Proxmox 中的对比 <a class="header-anchor" href="#三种存储方案在-proxmox-中的对比" aria-label="Permalink to &quot;三种存储方案在 Proxmox 中的对比&quot;">​</a></h2><h3 id="方案一-传统阵列-iscsi-fibre-channel" tabindex="-1">方案一：传统阵列（iSCSI / Fibre Channel） <a class="header-anchor" href="#方案一-传统阵列-iscsi-fibre-channel" aria-label="Permalink to &quot;方案一：传统阵列（iSCSI / Fibre Channel）&quot;">​</a></h3><p>Proxmox 基于 Debian Linux，内核可直接识别 iSCSI、Fibre Channel、直连设备。通过 <code>multipathd</code> 聚合多路径设备，使用共享厚置备 LVM（shared thick LVM）。</p><p><strong>局限：</strong></p><ul><li>不支持原生 thin provisioning，只能通过 TRIM 回收空间（&quot;信用卡 vs 退税&quot;的比喻）</li><li>快照依赖外部 QEMU 格式</li><li>LUN 在外部阵列上独立配置，与 hypervisor 无关联</li><li>存储路径冗长：控制器 → 多路径聚合 → LVM 物理卷 → 卷组 → Proxmox 共享</li></ul><h3 id="方案二-nfs" tabindex="-1">方案二：NFS <a class="header-anchor" href="#方案二-nfs" aria-label="Permalink to &quot;方案二：NFS&quot;">​</a></h3><p>NFS 在 Proxmox 中使用相对简单，多路径在网络层处理。但存在严重的 <strong>COW on COW（Copy-on-Write 叠加）</strong> 问题：</p><ul><li>操作系统使用 COW 文件系统</li><li>QEMU 存储格式使用 COW</li><li>后端如 ZFS/OpenZFS 也使用 COW</li></ul><p>计算结果：写放大可达 <strong>32 到 256 倍</strong>。在 QCOW2 格式的快照操作中尤为严重。NAS 头本身仍是单点故障和性能瓶颈。</p><h3 id="方案三-ceph-推荐" tabindex="-1">方案三：Ceph（推荐） <a class="header-anchor" href="#方案三-ceph-推荐" aria-label="Permalink to &quot;方案三：Ceph（推荐）&quot;">​</a></h3><p><strong>Ceph 与 Proxmox 的集成是最佳选择</strong>，原因如下：</p><h4 id="管理完全集成" tabindex="-1">管理完全集成 <a class="header-anchor" href="#管理完全集成" aria-label="Permalink to &quot;管理完全集成&quot;">​</a></h4><ul><li>Proxmox 围绕 Ceph 设计，使用上游代码，几乎无额外修改</li><li>超融合部署（hyper-converged）：计算节点即存储节点，一切在 Proxmox 内管理</li><li>外部 Ceph 集成只需一个 keyring：配置用户权限后共享给 Proxmox 即可</li><li>存储分配、迁移、扩容全部在 hypervisor 内完成</li></ul><h4 id="无瓶颈架构" tabindex="-1">无瓶颈架构 <a class="header-anchor" href="#无瓶颈架构" aria-label="Permalink to &quot;无瓶颈架构&quot;">​</a></h4><ul><li>客户端通过 librbd 直接与 OSD 通信，<strong>无控制器、无守门人</strong></li><li>MON 和 Manager 不在数据路径上，不影响 I/O 吞吐和可用性</li><li>CRUSH 算法（Controlled Replication Under Scalable Hashing）实现数据分布，Sage Weil 于 2005 年设计</li><li>有趣的是，Proxmox 同样诞生于 2005 年</li></ul><h4 id="高可用性" tabindex="-1">高可用性 <a class="header-anchor" href="#高可用性" aria-label="Permalink to &quot;高可用性&quot;">​</a></h4><ul><li>三副本 Ceph 可达到 <strong>六个九（99.9999%）</strong> 的可用性，相当于国际空间站级别</li><li>Ceph 原生提供多路径和冗余，无需额外配置</li></ul><h4 id="无写放大" tabindex="-1">无写放大 <a class="header-anchor" href="#无写放大" aria-label="Permalink to &quot;无写放大&quot;">​</a></h4><ul><li>Proxmox 将快照操作直接 offload 到 Ceph，直接使用 Ceph 原生快照</li><li>彻底避免 NFS 方案中的 COW on COW 写放大问题</li><li>克隆操作同样高效</li></ul><h2 id="存储栈对比" tabindex="-1">存储栈对比 <a class="header-anchor" href="#存储栈对比" aria-label="Permalink to &quot;存储栈对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>传统阵列</th><th>NFS</th><th>Ceph</th></tr></thead><tbody><tr><td>控制器瓶颈</td><td>有</td><td>有（NAS头）</td><td>无</td></tr><tr><td>单点故障</td><td>是</td><td>是</td><td>否</td></tr><tr><td>Thin Provisioning</td><td>仅 TRIM 回收</td><td>取决于后端</td><td>原生支持</td></tr><tr><td>快照机制</td><td>外部 QEMU</td><td>COW on COW 风险</td><td>Ceph 原生</td></tr><tr><td>管理复杂度</td><td>高（外部配置）</td><td>中</td><td>低（Proxmox 集成）</td></tr><tr><td>写放大</td><td>低</td><td>32-256x</td><td>无</td></tr><tr><td>厂商锁定</td><td>严重</td><td>部分</td><td>无</td></tr></tbody></table><h2 id="开源的价值" tabindex="-1">开源的价值 <a class="header-anchor" href="#开源的价值" aria-label="Permalink to &quot;开源的价值&quot;">​</a></h2><p>Alex 从实验室物理学家的视角阐述了选择开源的根本原因：</p><ol><li><strong>可回答性</strong>：闭源方案在某个层面就会触及专有 IP，无法进一步排查问题；开源则允许完全追溯问题根源</li><li><strong>对客户的责任</strong>：能够清晰地诊断和说明系统行为，是工程师对客户的基本承诺</li><li><strong>社区驱动</strong>：开源会议不会以&quot;我们是最好的，不要质疑&quot;开场，而是基于技术事实讨论</li></ol><h2 id="演讲者的行动建议" tabindex="-1">演讲者的行动建议 <a class="header-anchor" href="#演讲者的行动建议" aria-label="Permalink to &quot;演讲者的行动建议&quot;">​</a></h2><p>当前处于<strong>第一阶段</strong>：大量组织正在迁移到 Proxmox，但可能尚未意识到已打开了整个开源生态系统的大门。</p><p><strong>第二阶段建议</strong>：将存储也迁移到开源——Ceph 是最佳选择。Proxmox + Ceph 的组合提供了从 shell、Ansible、编排工具到 AI 编程助手的完整开放生态。鼓励用户积极寻求社区帮助，通过邮件列表、社区论坛等渠道获取支持。Ceph 不是另一个 RAID 阵列，而是一个完整的生态系统。</p>',38)])])}const u=a(l,[["render",i]]);export{c as __pageData,u as default};
